public class Invocation_callRealMethod_TriageGen1Test {

    @Test
    public void testCallRealMethod_ReturnsExpectedValue() throws Throwable {
        // Arrange
        Object mock = new Object();
        String expectedValue = "Hello Mockito";

        // We need a real method to invoke. 
        // Since Invocation uses realMethod.invoke(mock, rawArguments), 
        // we use a real class method via reflection.
        Method realMethod = String.class.getMethod("valueOf", String.class);
        Object[] rawArguments = new Object[]{"Hello Mockito"};

        // MockitoMethod is a dependency, we can pass null or a mock if it's not used in the method body
        MockitoMethod mockitoMethod = null; 

        // We need to reach the constructor. 
        // Note: In a real Mockito environment, Invocation is created internally.
        // Since we are testing the logic of callRealMethod:
        Invocation invocation = new Invocation(
                mock, 
                mockitoMethod, 
                rawArguments, 
                1, 
                realMethod
        );

        // Act
        Object result = invocation.callRealMethod();

        // Assert
        assertEquals(expectedValue, result);
    }

    @Test
    public void testCallRealMethod_ThrowsException() throws Throwable {
        // Arrange
        Object mock = new Object();
        // A method that throws an exception
        Method realMethod = RuntimeException.class.getMethod("throwException"); 
        // Note: Since we can't easily find a method that just throws without a class, 
        // we use a standard one that might fail or use reflection to wrap a lambda if possible.
        // For the sake of this unit test, let's use a method that throws an exception.

        Method errorMethod = Exception.class.getDeclaredMethod("toString"); 
        // This is tricky because we need a method that actually throws.
        // Let's use a method from a custom local class if allowed, 
        // but here we will use a method that is guaranteed to throw if we provide wrong args.

        Method badMethod = String.class.getMethod("substring", int, int);
        Object[] badArgs = new Object[]{10, 5}; // IndexOutOfBounds

        Invocation invocation = new Invocation(
                mock,
                null,
                badArgs,
                1,
                badMethod
        );

        // Act & Assert
        try {
            invocation.callRealMethod();
            org.junit.Assert.fail("Should have thrown an exception");
        } catch (Throwable t) {
            // Reflection wraps exceptions in InvocationTargetException
            // The method signature says 'throws Throwable', so we catch it.
            org.junit.Assert.assertTrue(t instanceof java.lang.IndexOutOfBoundsException || t instanceof java.lang.reflect.InvocationTargetException);
        }
    }

    @Test
    public void testCallRealMethod_WithVoidMethod() throws Throwable {
        // Arrange
        Object mock = new Object();
        Method voidMethod = System.out.getClass().getMethod("println", Object.class);
        Object[] args = new Object[]{"void test"};

        Invocation invocation = new Invocation(
                mock,
                null,
                args,
                1,
                voidMethod
        );

        // Act
        Object result = invocation.callRealMethod();

        // Assert
        assertNull(result);
    }
}

